import {getCurrentUser,signOut} from './auth.js';
import {list,insert,update,remove,count} from './db.js';
import {supabase} from './supabase.js';
import {CONFIG} from './config.js';
import {uploadDrive} from './drive.js';
import {buildWhatsAppLink,generatePdfReport} from './report.js';

const state={user:null,page:'home',cache:{}}; const app=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=x=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(Number(x)||0);
const today=()=>new Date().toISOString().slice(0,10);
const role=()=>state.user?.role||'student';
function toast(msg,bad=false){const e=document.createElement('div');e.className='toast '+(bad?'bad':'');e.textContent=msg;document.body.append(e);setTimeout(()=>e.remove(),2800)}
async function safe(fn){try{return await fn()}catch(e){console.error(e);toast(e.message||'Terjadi kesalahan',true);throw e}}
function stat(label,value,note=''){return `<div class="card stat"><small>${esc(label)}</small><strong>${esc(value)}</strong><span>${esc(note)}</span></div>`}
window.toast=toast; window.go=p=>{state.page=p;render()};
const menu={admin:[['home','Dashboard','⌂'],['accounts','Akun','♙'],['enrollments','Paket Siswa','▣'],['students','Siswa','♙'],['teachers','Guru','♟'],['classes','Kelas','▦'],['subjects','Mapel','◈'],['packages','Paket','▣'],['schedules','Jadwal Paket','◷'],['meetings','Pertemuan','◴'],['materials','Materi','▤'],['attendance','Absensi','✓'],['quizzes','Kuis','✓'],['tryouts','Tryout','◆'],['drill','Drill Harian','🎯'],['billing','Tagihan','Rp'],['reports','Laporan','▥'],['monitoring','Monitoring','◉']],teacher:[['home','Dashboard','⌂'],['students','Siswa','♙'],['schedules','Jadwal Mengajar','◷'],['meetings','Pertemuan','◴'],['materials','Materi','▤'],['attendance','Presensi','✓'],['quizzes','Kuis','✓'],['drill','Drill Harian','🎯'],['reports','Laporan','▥']],student:[['home','Dashboard','⌂'],['schedules','Jadwal Saya','◷'],['materials','Belajar','▤'],['drill','Drill Harian','🎯'],['quizzes','Kuis','✓'],['tryouts','Tryout','◆'],['reports','Nilai','▥'],['billing','Tagihan','Rp'],['profile','Profil','●']]};
function shell(){const items=menu[role()]||menu.student;app.innerHTML=`<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="brand"><img src="assets/logo.svg"><div><b>TRIPLE-F</b><small>EDUCATION</small></div></div><nav>${items.map(([p,n,i])=>`<button data-page="${p}">${i}<span>${n}</span></button>`).join('')}</nav><div class="side-user"><b>${esc(state.user.full_name)}</b><small>${esc(role())}</small></div><button id="logout" class="btn btn-soft btn-block">Keluar</button></aside><main class="main"><header class="topbar"><div><button class="menu-toggle" id="menubtn">☰</button><strong id="pageTitle">Dashboard</strong></div><div class="topbar-user"><span class="top-date">${new Intl.DateTimeFormat('id-ID',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).format(new Date())}</span><span class="badge">${esc(role()).toUpperCase()}</span><span class="avatar">${esc((state.user.full_name||'U').slice(0,1).toUpperCase())}</span></div></header><section class="content" id="content"></section></main></div>`;document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>{state.page=x.dataset.page;document.querySelector('#sidebar')?.classList.remove('open');render()});document.querySelector('#logout').onclick=signOut;document.querySelector('#menubtn').onclick=()=>document.querySelector('#sidebar').classList.toggle('open')}

async function getStudent(){
 const rows=await list('students',{filters:[{op:'eq',col:'profile_id',val:state.user.id}],limit:1});
 return rows[0]||null;
}
async function studentContext(){
 const st=await getStudent();
 if(!st) return {student:null,enrollments:[],schedules:[]};
 const enrollments=await list('student_packages',{select:'*,packages(name,class_id,classes(name))',filters:[{op:'eq',col:'student_id',val:st.id},{op:'eq',col:'status',val:'active'}],order:'start_date',ascending:false,limit:100});
 const pids=[...new Set(enrollments.map(x=>x.package_id).filter(Boolean))];
 let schedules=[];
 if(pids.length){
   schedules=await list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',filters:[{op:'in',col:'package_id',val:pids}],order:'weekday',ascending:true,limit:500});
 }
 return {student:st,enrollments,schedules};
}
const dayNames=['Minggu','Senin','Selasa','Rabu','Kamis','Jumat','Sabtu'];
function scheduleLabel(s){return `${dayNames[Number(s.weekday)]||'-'} • ${String(s.start_time||'').slice(0,5)}–${String(s.end_time||'').slice(0,5)}`}
async function home(){
 if(role()==='student'){
  const ctx=await studentContext(); const st=ctx.student;
  const [materials,drill]=await Promise.all([
   list('materials',{filters:[{op:'eq',col:'published',val:true}],limit:5}),
   st?list('drill_daily_targets',{filters:[{op:'eq',col:'student_id',val:st.id},{op:'eq',col:'date',val:today()}],limit:30}):[]
  ]);
  const d=drill.reduce((a,x)=>({target:a.target+Number(x.target_questions||0),done:a.done+Number(x.completed_questions||0)}),{target:0,done:0});
  const pct=d.target?Math.min(100,Math.round(d.done/d.target*100)):0;
  const cls=st?.class_id?((await list('classes',{filters:[{op:'eq',col:'id',val:st.class_id}],limit:1}))[0]||null):null;
  const activePackage=ctx.enrollments[0]?.packages;
  const todayNo=new Date().getDay();
  const todaySchedules=ctx.schedules.filter(x=>Number(x.weekday)===todayNo);
  return `<div class="page-title"><div><span class="eyebrow">DASHBOARD SISWA</span><h1>Selamat datang, ${esc(st?.full_name||state.user.full_name)} 👋</h1><p>${esc(st?.school||'Nama sekolah belum diisi')} • Kelas ${esc(cls?.name||'-')}</p></div><span class="badge">SISWA</span></div>
  <div class="student-identity card"><div><small>Sekolah</small><strong>${esc(st?.school||'Belum diisi')}</strong></div><div><small>Kelas</small><strong>${esc(cls?.name||'-')}</strong></div><div><small>Paket aktif</small><strong>${esc(activePackage?.name||'-')}</strong></div><div><small>Hari ini</small><strong>${esc(dayNames[todayNo])}</strong></div></div>
  <div class="cards">${stat('Target Drill Hari Ini',d.target+' soal','Target harian')}${stat('Selesai',d.done+' soal','Hari ini')}${stat('Progress',pct+'%','Drill')}${stat('Jadwal Hari Ini',todaySchedules.length,'Sesi')}</div>
  <div class="grid-2"><div class="card drill-card"><h3>🎯 DRILL SOAL HARIAN</h3><b class="drill-big">${d.done}/${d.target||0}</b><p>Soal selesai hari ini</p><div class="progress"><span style="width:${pct}%"></span></div><button class="btn light" onclick="go('drill')">MULAI / LANJUTKAN</button></div>
  <div class="card"><div class="section-head"><h3>📅 Jadwal Saya Hari Ini</h3><button class="link-btn" onclick="go('schedules')">Lihat semua</button></div>${todaySchedules.map(x=>`<div class="schedule-row"><div class="schedule-icon">${esc((x.subjects?.name||'M').slice(0,1))}</div><div><b>${esc(x.subjects?.name||'Sesi belajar')}</b><small>${esc(x.packages?.name||'')} • ${esc(x.classes?.name||'')}</small></div><strong>${esc(String(x.start_time||'').slice(0,5))}</strong></div>`).join('')||'<p class="muted">Tidak ada sesi belajar hari ini.</p>'}</div></div>
  <div class="grid-2"><div class="card"><h3>📚 Materi Terbaru</h3>${materials.map(m=>`<div class="list-item"><div><b>${esc(m.title)}</b><small>${esc(m.content_type||'materi')}</small></div></div>`).join('')||'<p class="muted">Belum ada materi.</p>'}</div><div class="card"><h3>ℹ️ Informasi Belajar</h3><p class="muted">Jadwal, kelas, paket dan sekolah ditampilkan dari data pendaftaranmu. Jika ada perubahan jadwal, guru/admin akan memperbaruinya.</p></div></div>`;
 }
 const [students,teachers,classes,bills,quizzes,tryouts]=await Promise.all([count('students'),count('teachers'),count('classes'),count('bills'),count('quizzes'),count('tryouts')]);
 if(role()==='teacher'){
   const tp=(await list('teachers',{filters:[{op:'eq',col:'profile_id',val:state.user.id}],limit:1}))[0]; const [me,qs]=await Promise.all([tp?list('meetings',{filters:[{op:'eq',col:'teacher_id',val:tp.id}],limit:20}):[],count('quizzes')]);
   return `<div class="page-title"><div><span class="eyebrow">DASHBOARD GURU</span><h1>Selamat datang, ${esc(state.user.full_name)} 👋</h1><p>Kelola jadwal, materi, presensi dan kuis sesuai sesi mengajar.</p></div><span class="badge">GURU</span></div><div class="cards">${stat('Siswa',students,'Data yang tersedia')}${stat('Pertemuan',me.length,'Jadwal')}${stat('Kuis',qs,'Evaluasi')}${stat('Drill','Aktif','Latihan harian')}</div><div class="grid-2"><div class="card"><h3>📅 Sesi Mengajar</h3><p class="muted">Gunakan menu Jadwal Mengajar untuk melihat kelas, paket, mapel dan waktu mengajar.</p><button class="btn btn-primary" onclick="go('schedules')">Lihat Jadwal</button></div><div class="card"><h3>✓ Presensi</h3><p class="muted">Presensi hanya ditampilkan berdasarkan sesi yang sesuai jadwal guru.</p><button class="btn btn-soft" onclick="go('attendance')">Buka Presensi</button></div></div>`;
 }
 return `<div class="page-title"><div><span class="eyebrow">DASHBOARD ADMIN</span><h1>Dashboard Admin</h1><p>Kelola seluruh data dan aktivitas TRIPLE-F EDUCATION.</p></div><span class="badge">ADMIN</span></div><div class="cards">${stat('Total Siswa',students,'Data aktif')}${stat('Total Guru',teachers,'Data aktif')}${stat('Kelas',classes,'Master')}${stat('Paket Aktif',bills,'Operasional')}${stat('Kuis',quizzes,'Evaluasi')}${stat('Tryout',tryouts,'Simulasi')}</div><div class="grid-2"><div class="card"><h3>⚡ Manajemen Cepat</h3><div class="quick"><button class="btn btn-primary" onclick="go('accounts')">+ Buat Akun</button><button class="btn btn-soft" onclick="go('students')">+ Siswa</button><button class="btn btn-soft" onclick="go('teachers')">+ Guru</button><button class="btn btn-soft" onclick="go('schedules')">+ Jadwal Paket</button><button class="btn btn-soft" onclick="go('quizzes')">+ Kuis</button></div></div><div class="card"><h3>🎯 Operasional</h3><p class="muted">Pastikan setiap paket memiliki jadwal, siswa aktif, guru pengajar dan kuis yang terhubung dengan sesi.</p></div></div>`;
}

async function schedules(){
 const isStudent=role()==='student';
 const isTeacher=role()==='teacher';
 let rows=[];
 if(isStudent){ rows=(await studentContext()).schedules; }
 else if(isTeacher){ const t=await list('teachers',{filters:[{op:'eq',col:'profile_id',val:state.user.id}],limit:1}); const tid=t[0]?.id; rows=tid?await list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',filters:[{op:'eq',col:'teacher_id',val:tid}],order:'weekday',ascending:true,limit:500}):[]; }
 else rows=await list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',order:'weekday',ascending:true,limit:500});
 document.querySelector('#pageTitle').textContent=isStudent?'Jadwal Saya':isTeacher?'Jadwal Mengajar':'Jadwal Paket';
 const add=isStudent||isTeacher?'':`<button class="btn btn-primary" id="addSchedule">+ Tambah Jadwal</button>`;
 document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>📅 ${isStudent?'Jadwal Saya':isTeacher?'Jadwal Mengajar':'Jadwal Paket'}</h1><p>${isStudent?'Jadwal sesuai paket belajar aktif dan kelasmu.':isTeacher?'Jadwal sesi yang menjadi tanggung jawabmu.':'Atur hari dan jam sesi untuk setiap paket belajar.'}</p></div>${add}</div><div class="schedule-board">${[1,2,3,4,5,6,0].map(d=>{const ds=rows.filter(x=>Number(x.weekday)===d);return `<div class="day-column"><div class="day-head"><b>${dayNames[d]}</b><span>${ds.length} sesi</span></div>${ds.map(x=>`<div class="schedule-card"><div class="schedule-time">${esc(String(x.start_time||'').slice(0,5))}–${esc(String(x.end_time||'').slice(0,5))}</div><h3>${esc(x.subjects?.name||'-')}</h3><p>${esc(x.packages?.name||'-')}</p><small>${esc(x.classes?.name||'-')} • ${esc(x.teachers?.full_name||'-')}</small>${!isStudent&&!isTeacher?`<div class="actions"><button class="icon" data-editschedule="${x.id}">Edit</button><button class="icon danger" data-delschedule="${x.id}">Hapus</button></div>`:''}</div>`).join('')||'<div class="empty-day">Tidak ada sesi</div>'}</div>`}).join('')}</div>`;
 if(!isStudent&&!isTeacher){document.querySelector('#addSchedule').onclick=()=>scheduleModal();document.querySelectorAll('[data-editschedule]').forEach(b=>b.onclick=()=>scheduleModal(rows.find(x=>x.id===b.dataset.editschedule)));document.querySelectorAll('[data-delschedule]').forEach(b=>b.onclick=async()=>{if(confirm('Hapus jadwal ini?')){await remove('package_schedules',b.dataset.delschedule);schedules()}})}
}
async function scheduleModal(row=null){
 const m=document.createElement('div');m.className='modal';const [packages,classes,subjects,teachers]=await Promise.all([getOptions('packages'),getOptions('classes'),getOptions('subjects'),getOptions('teachers')]);m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${row?'Edit':'Tambah'} Jadwal Paket</h3><button id="x">×</button></div><form id="sf"><label>Paket<select id="sp" required><option value="">-- pilih paket --</option>${packages.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Kelas<select id="sc" required><option value="">-- pilih kelas --</option>${classes.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Mata Pelajaran<select id="ss" required><option value="">-- pilih mapel --</option>${subjects.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Guru<select id="st" required><option value="">-- pilih guru --</option>${teachers.map(x=>`<option value="${x.id}">${esc(x.full_name)}</option>`).join('')}</select></label><label>Hari<select id="sw" required>${[1,2,3,4,5,6,0].map(d=>`<option value="${d}">${dayNames[d]}</option>`).join('')}</select></label><div class="form-grid"><label>Mulai<input id="sstart" type="time" required></label><label>Selesai<input id="send" type="time" required></label></div><label>Ruangan / Link<input id="room" value="${esc(row?.room||'')}"></label><div class="modal-actions"><button type="button" id="c" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div>`;document.body.append(m);if(row){sp.value=row.package_id||'';sc.value=row.class_id||'';ss.value=row.subject_id||'';st.value=row.teacher_id||'';sw.value=String(row.weekday);sstart.value=String(row.start_time||'').slice(0,5);send.value=String(row.end_time||'').slice(0,5)}const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#c').onclick=close;m.querySelector('#sf').onsubmit=async e=>{e.preventDefault();await safe(async()=>{const data={package_id:sp.value,class_id:sc.value,subject_id:ss.value,teacher_id:st.value,weekday:Number(sw.value),start_time:sstart.value,end_time:send.value,room:room.value||null,status:'active'};if(row)await update('package_schedules',row.id,data);else await insert('package_schedules',data);toast('Jadwal tersimpan');close();schedules()})}}

const configs={
 students:{title:'Data Siswa',desc:'Kelola identitas siswa dan akun login.',table:'students',cols:[['Kode',r=>esc(r.student_code)],['Nama',r=>esc(r.full_name)],['Sekolah',r=>esc(r.school)],['Kelas',r=>esc(r.classes?.name||'-')],['Status',r=>esc(r.status)]]},
 teachers:{title:'Data Guru',desc:'Kelola guru dan spesialisasi.',table:'teachers',cols:[['Kode',r=>esc(r.teacher_code)],['Nama',r=>esc(r.full_name)],['Spesialisasi',r=>esc(r.specialization)],['Status',r=>esc(r.status)]]},
 classes:{title:'Kelas',desc:'Master kelas belajar.',table:'classes',cols:[['Nama',r=>esc(r.name)],['Level',r=>esc(r.level)],['Status',r=>esc(r.status)]]},
 subjects:{title:'Mata Pelajaran',desc:'Master mata pelajaran.',table:'subjects',cols:[['Nama',r=>esc(r.name)],['Status',r=>esc(r.status)]]},
 packages:{title:'Paket Belajar',desc:'Paket, harga dan periode belajar.',table:'packages',cols:[['Nama',r=>esc(r.name)],['Kelas',r=>esc(r.classes?.name||'-')],['Harga',r=>money(r.price)],['Durasi',r=>esc(r.duration_month)+' bln'],['Status',r=>esc(r.status)]]},
 schedules:{title:'Jadwal Paket',desc:'Jadwal paket belajar per hari, jam, guru dan mapel.',table:'package_schedules',cols:[['Hari',r=>esc(dayNames[Number(r.weekday)]||'-')],['Jam',r=>esc(String(r.start_time||'').slice(0,5)+'–'+String(r.end_time||'').slice(0,5))],['Paket',r=>esc(r.packages?.name||'-')],['Kelas',r=>esc(r.classes?.name||'-')],['Mapel',r=>esc(r.subjects?.name||'-')],['Guru',r=>esc(r.teachers?.full_name||'-')]]},
 meetings:{title:'Pertemuan',desc:'Detail pertemuan dan materi pembelajaran.',table:'meetings',cols:[['No',r=>r.meeting_number],['Judul',r=>esc(r.title)],['Tanggal',r=>esc(r.meeting_date)],['Guru',r=>esc(r.teachers?.full_name||'-')],['Status',r=>esc(r.status)]]},
 materials:{title:'Materi',desc:'Materi teks, tautan atau file Google Drive.',table:'materials',cols:[['Judul',r=>esc(r.title)],['Tipe',r=>esc(r.content_type)],['Terbit',r=>r.published?'Ya':'Draft'],['File',r=>r.drive_url?`<a href="${esc(r.drive_url)}" target="_blank">Buka</a>`:'-']]},
 enrollments:{title:'Paket Siswa',desc:'Hubungkan siswa dengan paket dan periode belajar.',table:'student_packages',cols:[['Siswa',r=>esc(r.students?.full_name||'-')],['Paket',r=>esc(r.packages?.name||'-')],['Mulai',r=>esc(r.start_date)],['Selesai',r=>esc(r.end_date)],['Status',r=>esc(r.status)]]},
 billing:{title:'Tagihan',desc:'Tagihan dan pembayaran siswa.',table:'bills',cols:[['No',r=>esc(r.bill_number)],['Siswa',r=>esc(r.students?.full_name||'-')],['Jumlah',r=>money(r.amount)],['Jatuh tempo',r=>esc(r.due_date)],['Status',r=>esc(r.status)]]}
};
const selects={package_schedules:['package_schedules','weekday'],classes:['classes','name'],subjects:['subjects','name'],packages:['packages','name'],teachers:['teachers','full_name'],students:['students','full_name'],meetings:['meetings','title'],profiles:['profiles','full_name'],quizzes:['quizzes','title'],tryouts:['tryouts','title'],drill_programs:['drill_programs','name']};
async function getOptions(key){const [table,col]=selects[key];return list(table,{select:'*',order:col,ascending:true,limit:500})}
function inputField(k,label,type,val='',extra=''){return `<label>${esc(label)}<input id="f_${k}" type="${type}" value="${esc(val??'')}" ${extra}></label>`}
async function fields(table,row={}){
 const f={students:[['student_code','Kode siswa','text'],['profile_id','Akun login','select:profiles'],['full_name','Nama lengkap','text'],['email','Email','email'],['phone','No. HP','text'],['class_id','Kelas','select:classes'],['birth_date','Tanggal lahir','date'],['school','Sekolah','text'],['parent_name','Nama orang tua','text'],['parent_phone','HP orang tua','text'],['address','Alamat','textarea']],teachers:[['teacher_code','Kode guru','text'],['profile_id','Akun login','select:profiles'],['full_name','Nama lengkap','text'],['email','Email','email'],['phone','No. HP','text'],['specialization','Spesialisasi','text']],classes:[['name','Nama kelas','text'],['level','Jenjang/Level','text'],['description','Deskripsi','textarea']],subjects:[['name','Nama mapel','text']],packages:[['name','Nama paket','text'],['description','Deskripsi','textarea'],['class_id','Kelas','select:classes'],['price','Harga','number'],['duration_month','Durasi (bulan)','number']],package_schedules:[['package_id','Paket','select:packages'],['class_id','Kelas','select:classes'],['subject_id','Mata Pelajaran','select:subjects'],['teacher_id','Guru','select:teachers'],['weekday','Hari','select:weekdays'],['start_time','Mulai','time'],['end_time','Selesai','time'],['room','Ruangan / Link','text'],['status','Status','text']],meetings:[['meeting_number','Nomor pertemuan','number'],['title','Judul','text'],['description','Deskripsi','textarea'],['class_id','Kelas','select:classes'],['package_id','Paket','select:packages'],['teacher_id','Guru','select:teachers'],['subject_id','Mapel','select:subjects'],['meeting_date','Tanggal','date'],['start_time','Mulai','time'],['end_time','Selesai','time'],['status','Status','text']],materials:[['title','Judul materi','text'],['description','Deskripsi','textarea'],['meeting_id','Pertemuan','select:meetings'],['teacher_id','Guru','select:teachers'],['class_id','Kelas','select:classes'],['package_id','Paket','select:packages'],['subject_id','Mapel','select:subjects'],['content_type','Tipe materi','text'],['content','Isi materi / HTML','textarea'],['published','Publikasikan','checkbox'],['file','Upload file ke Google Drive','file'],['drive_url','URL Drive','url']],enrollments:[['student_id','Siswa','select:students'],['package_id','Paket','select:packages'],['start_date','Mulai','date'],['end_date','Selesai','date'],['status','Status','text']],billing:[['bill_number','Nomor tagihan','text'],['student_id','Siswa','select:students'],['package_id','Paket','select:packages'],['period_start','Periode mulai','date'],['period_end','Periode akhir','date'],['amount','Jumlah','number'],['due_date','Jatuh tempo','date'],['status','Status','text']]}[table]||[];
 let out=''; for(const [k,l,t] of f){if(t==='file')out+=`<label>${esc(l)}<input id="f_${k}" type="file" accept=".pdf,.jpg,.jpeg,.png,.webp,.doc,.docx,.ppt,.pptx"></label>`;else if(t==='textarea')out+=`<label>${esc(l)}<textarea id="f_${k}">${esc(row[k]||'')}</textarea></label>`;else if(t==='checkbox')out+=`<label class="checkline"><input id="f_${k}" type="checkbox" ${row[k]?'checked':''}> ${esc(l)}</label>`;else if(t.startsWith('select:')){const src=t.slice(7),rows=await getOptions(src);out+=`<label>${esc(l)}<select id="f_${k}"><option value="">-- Pilih --</option>${rows.map(x=>`<option value="${x.id}" ${row[k]===x.id?'selected':''}>${esc(x.full_name||x.name||x.title||'-')}</option>`).join('')}</select></label>`}else out+=inputField(k,l,t,row[k]??'',t==='number'?'min="0"':'')}return out;
}
async function formModal(table,row=null,onDone=()=>render()){const modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${row?'Edit':'Tambah'} ${esc(configs[table]?.title||table)}</h3><button id="close">×</button></div><form id="form"><div id="dynamicFields">Memuat...</div><div class="modal-actions"><button type="button" id="cancel" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div>`;document.body.append(modal);document.querySelector('#dynamicFields').innerHTML=await fields(table,row||{});const close=()=>modal.remove();document.querySelector('#close').onclick=document.querySelector('#cancel').onclick=close;document.querySelector('#form').onsubmit=async e=>{e.preventDefault();const obj={};document.querySelectorAll('#form [id^="f_"]').forEach(x=>{const k=x.id.slice(2);if(x.type==='file')return;obj[k]=x.type==='checkbox'?x.checked:(x.value===''?null:(x.type==='number'?Number(x.value):x.value))});await safe(async()=>{const file=document.querySelector('#f_file')?.files?.[0];if(file){const u=await uploadDrive(file,'01_MATERI');obj.drive_file_id=u.fileId||u.id||null;obj.drive_url=u.url||u.webViewLink||null;obj.file_name=file.name;obj.file_type=file.type;obj.file_size=file.size}await(row?update(table,row.id,obj):insert(table,obj))});close();toast('Data tersimpan');onDone()}}
async function genericTable(page){const cfg=configs[page];const select=page==='enrollments'?'*,students(full_name),packages(name)':page==='students'?'*,classes(name)':page==='teachers'?'*':page==='packages'?'*,classes(name)':page==='schedules'?'*,packages(name),classes(name),subjects(name),teachers(full_name)':page==='meetings'?'*,teachers(full_name)':page==='billing'?'*,students(full_name)': '*';const rows=await list(cfg.table,{select,order:'created_at',ascending:false,limit:500});state.cache[cfg.table]=rows;document.querySelector('#pageTitle').textContent=cfg.title;document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>${cfg.title}</h1><p>${cfg.desc}</p></div><button class="btn btn-primary" id="add">+ Tambah</button></div><div class="card"><div class="toolbar"><input id="search" class="search" placeholder="Cari..."><span class="muted">${rows.length} data</span></div><div class="table-wrap"><table class="table"><thead><tr>${cfg.cols.map(c=>`<th>${c[0]}</th>`).join('')}<th>Aksi</th></tr></thead><tbody>${rows.map(r=>`<tr>${cfg.cols.map(c=>`<td>${c[1](r)}</td>`).join('')}<td class="actions"><button class="icon" data-edit="${r.id}">Edit</button><button class="icon danger" data-del="${r.id}">Hapus</button></td></tr>`).join('')||`<tr><td colspan="${cfg.cols.length+1}" class="empty">Belum ada data.</td></tr>`}</tbody></table></div></div>`;document.querySelector('#add').onclick=()=>formModal(cfg.table);document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>formModal(cfg.table,rows.find(r=>r.id===b.dataset.edit)));document.querySelectorAll('[data-del]').forEach(b=>b.onclick=async()=>{if(confirm('Hapus data ini?')){await safe(()=>remove(cfg.table,b.dataset.del));toast('Data dihapus');render()}});document.querySelector('#search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('tbody tr').forEach(tr=>tr.style.display=tr.textContent.toLowerCase().includes(q)?'':'none')}}

async function accounts(){document.querySelector('#pageTitle').textContent='Akun Pengguna';const profiles=await list('profiles',{order:'created_at',ascending:false,limit:500});document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>Akun Pengguna</h1><p>Buat akun Admin, Guru atau Siswa tanpa membuka SQL.</p></div><button class="btn btn-primary" id="addAccount">+ Buat Akun</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Nama</th><th>Email</th><th>Peran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${profiles.map(p=>`<tr><td>${esc(p.full_name)}</td><td>${esc(p.email)}</td><td>${esc(p.role)}</td><td>${esc(p.status)}</td><td><button class="icon" data-role="${p.id}">Peran</button></td></tr>`).join('')}</tbody></table></div></div>`;document.querySelector('#addAccount').onclick=accountModal;document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>roleModal(profiles.find(p=>p.id===b.dataset.role)))}
async function accountModal(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>Buat Akun</h3><button id="x">×</button></div><form id="af"><label>Nama lengkap<input id="an" required></label><label>Email<input id="ae" type="email" required></label><label>Password awal<input id="ap" type="password" minlength="8" required></label><label>Peran<select id="ar"><option value="student">Siswa</option><option value="teacher">Guru</option><option value="admin">Admin</option></select></label><label>No. HP<input id="aph"></label><div id="studentExtra"></div><div class="modal-actions"><button type="button" id="ac" class="btn btn-soft">Batal</button><button class="btn btn-primary">Buat Akun</button></div></form></div>`;document.body.append(m);const fillExtra=async()=>{const holder=m.querySelector('#studentExtra');holder.innerHTML=ar.value==='student'?`<label>Kelas<select id="aclass"><option value="">--</option>${(await getOptions('classes')).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Sekolah<input id="aschool"></label><label>Nama orang tua<input id="aparent"></label><label>HP orang tua<input id="aparentphone"></label>`:ar.value==='teacher'?`<label>Spesialisasi<input id="aspec"></label>`:''};m.querySelector('#ar').onchange=fillExtra;await fillExtra();const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#ac').onclick=close;m.querySelector('#af').onsubmit=async e=>{e.preventDefault();await safe(async()=>{if(!CONFIG.ACCOUNT_API_URL||CONFIG.ACCOUNT_API_URL.includes('PASTE_'))throw Error('ACCOUNT_API_URL belum diisi. Deploy Supabase Edge Function sesuai SETUP.md.');const s=await supabase();const {data:{session}}=await s.auth.getSession();const r=await fetch(CONFIG.ACCOUNT_API_URL,{method:'POST',headers:{Authorization:`Bearer ${session.access_token}`,'Content-Type':'application/json'},body:JSON.stringify({full_name:an.value,email:ae.value,password:ap.value,role:ar.value,phone:aph.value,class_id:m.querySelector('#aclass')?.value||null,school:m.querySelector('#aschool')?.value||null,parent_name:m.querySelector('#aparent')?.value||null,parent_phone:m.querySelector('#aparentphone')?.value||null,specialization:m.querySelector('#aspec')?.value||null})});const j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Gagal membuat akun');toast('Akun berhasil dibuat');close();render()})}}
async function roleModal(p){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>Ubah Peran</h3><button id="x">×</button></div><form id="rf"><p>${esc(p.full_name)} — ${esc(p.email)}</p><label>Peran<select id="rr"><option ${p.role==='student'?'selected':''}>student</option><option ${p.role==='teacher'?'selected':''}>teacher</option><option ${p.role==='admin'?'selected':''}>admin</option></select></label><div class="modal-actions"><button type="button" id="c" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div>`;document.body.append(m);const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#c').onclick=close;m.querySelector('#rf').onsubmit=async e=>{e.preventDefault();await safe(()=>update('profiles',p.id,{role:m.querySelector('#rr').value}));toast('Peran diperbarui');close();render()}}

async function questionBank(kind){const table=kind==='quiz'?'quizzes':'tryouts';const qtable=kind==='quiz'?'quiz_questions':'tryout_questions';const ot=kind==='quiz'?'quiz_options':'tryout_options';const sets=await list(table,{order:'created_at',ascending:false,limit:500});document.querySelector('#pageTitle').textContent=kind==='quiz'?'Kuis':'Tryout';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>${kind==='quiz'?'📝 Kuis':'🧪 Tryout'}</h1><p>${kind==='quiz'&&role()==='teacher'?'Buat kuis yang terhubung dengan jadwal sesi mengajar, lalu kelola bank soalnya.':'Kelola paket evaluasi dan bank soal.'}</p></div><button class="btn btn-primary" id="addSet">+ Tambah</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Judul</th><th>Durasi</th><th>Soal</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${sets.map(s=>`<tr><td>${esc(s.title)}</td><td>${s.duration_minutes} mnt</td><td>${s.question_count||'—'}</td><td>${esc(s.status)}</td><td><button class="icon" data-bank="${s.id}">Bank Soal</button><button class="icon" data-editset="${s.id}">Edit</button></td></tr>`).join('')||'<tr><td colspan="5">Belum ada.</td></tr>'}</tbody></table></div></div>`;document.querySelector('#addSet').onclick=()=>setModal(kind);document.querySelectorAll('[data-editset]').forEach(b=>b.onclick=()=>setModal(kind,sets.find(x=>x.id===b.dataset.editset)));document.querySelectorAll('[data-bank]').forEach(b=>b.onclick=()=>questionList(kind,b.dataset.bank))}
async function setModal(kind,row=null){const table=kind==='quiz'?'quizzes':'tryouts';const m=document.createElement('div');m.className='modal';const [classes,subjects,schedulesOpt]=await Promise.all([getOptions('classes'),getOptions('subjects'),list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',order:'weekday',ascending:true,limit:500})]);const scheduleRows=schedulesOpt.filter(x=>x.status==='active');m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${row?'Edit':'Tambah'} ${kind==='quiz'?'Kuis':'Tryout'}</h3><button id="x">×</button></div><form id="sf"><label>Judul<input id="st" required value="${esc(row?.title||'')}"></label><label>Deskripsi<textarea id="sd">${esc(row?.description||'')}</textarea></label>${kind==='quiz'?`<label>Jadwal sesi<select id="ssch"><option value="">-- pilih jadwal sesi --</option>${scheduleRows.map(x=>`<option value="${x.id}" ${row?.schedule_id===x.id?'selected':''}>${esc(dayNames[Number(x.weekday)])} ${esc(String(x.start_time||'').slice(0,5))}–${esc(String(x.end_time||'').slice(0,5))} • ${esc(x.subjects?.name||'-')} • ${esc(x.classes?.name||'-')} • ${esc(x.teachers?.full_name||'-')}</option>`).join('')}</select></label>`:''}<label>Kelas<select id="sc"><option value="">Semua</option>${classes.map(x=>`<option value="${x.id}" ${row?.class_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Mapel<select id="ss"><option value="">Semua</option>${subjects.map(x=>`<option value="${x.id}" ${row?.subject_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Durasi (menit)<input id="sm" type="number" min="1" value="${row?.duration_minutes||60}"></label><label>Batas percobaan<input id="sl" type="number" min="1" value="${row?.attempt_limit||1}"></label><label>Status<select id="sx"><option value="draft">draft</option><option value="published">published</option><option value="closed">closed</option></select></label><div class="modal-actions"><button type="button" id="c" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div>`;document.body.append(m);if(row)m.querySelector('#sx').value=row.status||'draft';const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#c').onclick=close;m.querySelector('#sf').onsubmit=async e=>{e.preventDefault();const o={title:st.value,description:sd.value,class_id:sc.value||null,subject_id:ss.value||null,duration_minutes:Number(sm.value),attempt_limit:Number(sl.value),status:sx.value};if(kind==='quiz'){if(role()==='teacher'&&!ssch.value)throw Error('Kuis guru harus terhubung ke jadwal sesi.');o.schedule_id=ssch?.value||null;if(o.schedule_id){const sr=(await list('package_schedules',{filters:[{op:'eq',col:'id',val:o.schedule_id}],limit:1}))[0];if(sr){o.package_id=sr.package_id;o.class_id=sr.class_id;o.subject_id=sr.subject_id;}}}if(kind==='tryout')o.question_count=row?.question_count||0;await safe(()=>row?update(table,row.id,o):insert(table,o));toast('Tersimpan');close();render()}}
async function questionList(kind,setId){const qtable=kind==='quiz'?'quiz_questions':'tryout_questions',ot=kind==='quiz'?'quiz_options':'tryout_options';const qs=await list(qtable,{filters:[{op:'eq',col:kind==='quiz'?'quiz_id':'tryout_id',val:setId}],order:'created_at',ascending:true,limit:1000});document.querySelector('#pageTitle').textContent='Bank Soal';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>📚 Bank Soal</h1><p>${qs.length} soal — klik tambah untuk memasukkan soal.</p></div><div class="quick"><button class="btn btn-soft" id="back">Kembali</button><button class="btn btn-primary" id="addQ">+ Soal</button></div></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>Pertanyaan</th><th>Kunci</th><th>Aksi</th></tr></thead><tbody>${qs.map((q,i)=>`<tr><td>${i+1}</td><td>${esc(q.question_text).slice(0,150)}</td><td>${esc(q.answer_key||'')}</td><td><button class="icon" data-qedit="${q.id}">Edit</button><button class="icon danger" data-qdel="${q.id}">Hapus</button></td></tr>`).join('')||'<tr><td colspan="4">Belum ada soal.</td></tr>'}</tbody></table></div></div>`;document.querySelector('#back').onclick=()=>questionBank(kind);document.querySelector('#addQ').onclick=()=>questionModal(kind,setId);document.querySelectorAll('[data-qedit]').forEach(b=>b.onclick=()=>questionModal(kind,setId,qs.find(q=>q.id===b.dataset.qedit)));document.querySelectorAll('[data-qdel]').forEach(b=>b.onclick=async()=>{if(confirm('Hapus soal?')){await safe(()=>remove(qtable,b.dataset.qdel));toast('Soal dihapus');questionList(kind,setId)}})}
async function questionModal(kind,setId,row=null){const qtable=kind==='quiz'?'quiz_questions':'tryout_questions',ot=kind==='quiz'?'quiz_options':'tryout_options';const opts=row?await list(ot,{filters:[{op:'eq',col:'question_id',val:row.id}],order:'option_key',ascending:true}):[];const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box modal-wide"><div class="modal-head"><h3>${row?'Edit':'Tambah'} Soal</h3><button id="x">×</button></div><form id="qf"><label>Pertanyaan<textarea id="qt" required>${esc(row?.question_text||'')}</textarea></label><label>Rumus (LaTeX/KaTeX)<input id="qformula" value="${esc(row?.formula||'')}"></label><label>URL gambar<input id="qimg" type="url" value="${esc(row?.image_url||'')}"></label><label>Penjelasan<textarea id="qexp">${esc(row?.explanation||'')}</textarea></label><label>Kunci jawaban<input id="qkey" placeholder="A atau A,B" value="${esc(row?.answer_key||'')}"></label><label>Bobot<input id="qw" type="number" min="0" step="0.1" value="${row?.weight||1}"></label><h4>Pilihan Jawaban</h4><div id="opts">${['A','B','C','D','E'].map(k=>{const o=opts.find(x=>x.option_key===k)||{};return `<label>${k}<input data-ok="${k}" value="${esc(o.option_text||'')}"></label>`}).join('')}</div><div class="modal-actions"><button type="button" id="c" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan Soal</button></div></form></div>`;document.body.append(m);const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#c').onclick=close;m.querySelector('#qf').onsubmit=async e=>{e.preventDefault();await safe(async()=>{const o={question_text:qt.value,image_url:qimg.value||null,formula:qformula.value||null,explanation:qexp.value||null,answer_key:qkey.value.trim().toUpperCase(),weight:Number(qw.value)||1};if(kind==='quiz')o.quiz_id=setId;else o.tryout_id=setId;const q=row?await update(qtable,row.id,o):await insert(qtable,o);if(row)await Promise.all(opts.map(x=>remove(ot,x.id)));const vals=[...m.querySelectorAll('[data-ok]')].map(x=>({question_id:q.id,option_key:x.dataset.ok,option_text:x.value.trim()})).filter(x=>x.option_text);if(vals.length)await Promise.all(vals.map(x=>insert(ot,x)));if(kind==='tryout')await update('tryouts',setId,{question_count:await countQuestions(qtable,kind,setId)});toast('Soal tersimpan');close();questionList(kind,setId)})}}
async function countQuestions(qtable,kind,id){return (await list(qtable,{filters:[{op:'eq',col:kind==='quiz'?'quiz_id':'tryout_id',val:id}],limit:5000})).length}

async function studentTests(kind){const table=kind==='quiz'?'quizzes':'tryouts';let sets=await list(table,{filters:[{op:'eq',col:'status',val:'published'}],order:'created_at',ascending:false});if(kind==='quiz'){const ctx=await studentContext();const pids=new Set(ctx.enrollments.map(x=>x.package_id));const cid=ctx.student?.class_id;sets=sets.filter(x=>(!x.package_id||pids.has(x.package_id))&&(!x.class_id||x.class_id===cid));}document.querySelector('#pageTitle').textContent=kind==='quiz'?'Kuis':'Tryout';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>${kind==='quiz'?'📝 Kuis Saya':'🧪 Tryout Saya'}</h1><p>${kind==='quiz'?'Kuis yang tersedia sesuai kelas dan paket belajar aktif.':'Simulasi yang tersedia.'}</p></div></div><div class="cards">${sets.map(s=>`<div class="card"><h3>${esc(s.title)}</h3><p>${s.duration_minutes} menit • maksimal ${s.attempt_limit||1} kali</p><button class="btn btn-primary" data-start="${s.id}">Mulai</button></div>`).join('')||'<div class="card">Belum ada evaluasi untuk kelas/paketmu.</div>'}</div>`;document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startPlayer(kind,b.dataset.start))}
async function getStudentId(){const st=await getStudent();return st?.id||null}
async function rpc(name,args){const s=await supabase();const {data,error}=await s.rpc(name,args);if(error)throw error;return data}
async function startPlayer(kind,setId){const student=await getStudentId();if(!student)throw Error('Profil siswa belum terhubung.');const info=await rpc(kind==='quiz'?'start_quiz_attempt':'start_tryout_attempt',{p_set_id:setId,p_student_id:student});const questions=info.questions||[];player(kind,info,questions)}
function player(kind,info,questions){let idx=0;const answers={};let remaining=Number(info.duration_seconds||info.duration_minutes*60||3600);const title=info.title||'Evaluasi';document.querySelector('#pageTitle').textContent=title;document.querySelector('#content').innerHTML=`<div class="exam"><div class="exam-head"><div><h1>${esc(title)}</h1><small id="timer">${fmtTime(remaining)}</small></div><span class="badge">${kind==='quiz'?'KUIS':'TRYOUT'}</span></div><div class="exam-grid"><aside class="question-nav">${questions.map((_,i)=>`<button data-i="${i}">${i+1}</button>`).join('')}</aside><main class="card exam-main"><div id="qbox"></div><div class="modal-actions"><button class="btn btn-soft" id="prev">Kembali</button><button class="btn btn-primary" id="next">Lanjut</button><button class="btn btn-primary" id="submit" style="display:none">Kumpulkan</button></div></main></div></div>`;
 const renderQ=()=>{const q=questions[idx];document.querySelector('#qbox').innerHTML=`<div class="question-count">Soal ${idx+1} dari ${questions.length}</div><h2>${esc(q.question_text)}</h2>${q.image_url?`<img class="question-image" src="${esc(q.image_url)}">`:''}${q.formula?`<div class="formula">${esc(q.formula)}</div>`:''}<div class="options">${(q.options||[]).map(o=>`<label class="option"><input type="radio" name="answer" value="${esc(o.option_key)}" ${answers[q.id]===o.option_key?'checked':''}> <b>${esc(o.option_key)}.</b> ${esc(o.option_text)}</label>`).join('')}</div>`;document.querySelectorAll('input[name=answer]').forEach(x=>x.onchange=()=>{answers[q.id]=x.value;document.querySelector(`[data-i="${idx}"]`).classList.add('done');});document.querySelectorAll('.question-nav button').forEach(x=>x.classList.toggle('active',Number(x.dataset.i)===idx));document.querySelector('#prev').disabled=idx===0;document.querySelector('#next').style.display=idx===questions.length-1?'none':'';document.querySelector('#submit').style.display=idx===questions.length-1?'':'none'};
 const submit=async()=>{clearInterval(timer);await safe(async()=>{const result=await rpc(kind==='quiz'?'submit_quiz_attempt':'submit_tryout_attempt',{p_attempt_id:info.attempt_id,p_answers:answers});document.querySelector('#content').innerHTML=`<div class="card hero"><h2>Hasil ${kind==='quiz'?'Kuis':'Tryout'}</h2><div class="cards">${stat('Benar',result.correct_answers)}${stat('Salah',result.wrong_answers)}${stat('Kosong',result.blank_answers??0)}${stat('Nilai',result.score)}</div><button class="btn btn-primary" onclick="go('reports')">Lihat Nilai</button></div>`})};
 document.querySelector('#prev').onclick=()=>{if(idx>0){idx--;renderQ()}};document.querySelector('#next').onclick=()=>{if(idx<questions.length-1){idx++;renderQ()}};document.querySelector('#submit').onclick=submit;document.querySelectorAll('.question-nav button').forEach(x=>x.onclick=()=>{idx=Number(x.dataset.i);renderQ()});renderQ();const timer=setInterval(()=>{remaining--;document.querySelector('#timer').textContent=fmtTime(Math.max(0,remaining));if(remaining<=0)submit()},1000)}
const fmtTime=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;

async function drill(){if(role()==='student')return studentDrill();const programs=await list('drill_programs',{select:'*,classes(name),subjects(name),packages(name)',order:'created_at',ascending:false});document.querySelector('#pageTitle').textContent='Drill Soal Harian';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>🎯 Drill Soal Harian</h1><p>Program, target efektif dan bank soal.</p></div><button class="btn btn-primary" id="addD">+ Program Drill</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Program</th><th>Kelas</th><th>Mapel</th><th>Total</th><th>Periode</th><th>Aksi</th></tr></thead><tbody>${programs.map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.classes?.name||'-')}</td><td>${esc(p.subjects?.name||'-')}</td><td>${p.total_questions}</td><td>${p.start_date} s/d ${p.end_date}</td><td><button class="icon" data-dq="${p.id}">Bank Soal</button></td></tr>`).join('')||'<tr><td colspan="6">Belum ada program.</td></tr>'}</tbody></table></div></div>`;document.querySelector('#addD').onclick=drillProgramModal;document.querySelectorAll('[data-dq]').forEach(b=>b.onclick=()=>drillQuestions(b.dataset.dq))}
async function drillProgramModal(){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>Program Drill</h3><button id="x">×</button></div><form id="df"><label>Nama program<input id="dn" required></label><label>Paket<select id="dp"><option value="">--</option>${(await getOptions('packages')).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Kelas<select id="dc"><option value="">--</option>${(await getOptions('classes')).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Mapel<select id="ds"><option value="">--</option>${(await getOptions('subjects')).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label>Topik<input id="dt"></label><label>Mulai<input id="dstart" type="date" required></label><label>Selesai<input id="dend" type="date" required></label><label>Total target soal<input id="dtotal" type="number" min="1" required></label><label>Durasi/soal (detik)<input id="ddur" type="number" min="0" value="0"></label><label>Hari efektif</label><div class="checks">${[['1','Senin'],['2','Selasa'],['3','Rabu'],['4','Kamis'],['5','Jumat'],['6','Sabtu']].map(x=>`<label><input type="checkbox" name="wd" value="${x[0]}" checked> ${x[1]}</label>`).join('')}</div><div class="modal-actions"><button type="button" id="c" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div>`;document.body.append(m);const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#c').onclick=close;m.querySelector('#df').onsubmit=async e=>{e.preventDefault();await safe(async()=>{const p=await insert('drill_programs',{name:dn.value,package_id:dp.value||null,class_id:dc.value||null,subject_id:ds.value||null,topic:dt.value||null,start_date:dstart.value,end_date:dend.value,total_questions:Number(dtotal.value),effective_days:document.querySelectorAll('input[name=wd]:checked').length,duration_minutes:Number(ddur.value)||0,status:'active'});const days=[...document.querySelectorAll('input[name=wd]:checked')];if(days.length)await Promise.all(days.map(x=>insert('drill_schedules',{drill_program_id:p.id,weekday:Number(x.value),is_effective:true})));await rpc('generate_drill_targets',{p_date:today()});toast('Program drill dibuat');close();render()})}}
async function drillQuestions(id){const qs=await list('drill_questions',{filters:[{op:'eq',col:'drill_program_id',val:id}],order:'created_at',ascending:true,limit:1000});document.querySelector('#pageTitle').textContent='Bank Soal Drill';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>Bank Soal Drill</h1><p>${qs.length} soal</p></div><button class="btn btn-primary" id="addDQ">+ Soal</button></div><div class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Pertanyaan</th><th>Kesulitan</th><th>Kunci</th><th>Aksi</th></tr></thead><tbody>${qs.map(q=>`<tr><td>${esc(q.question_text).slice(0,150)}</td><td>${esc(q.difficulty)}</td><td>${esc(q.answer_key)}</td><td><button class="icon" data-editdq="${q.id}">Edit</button><button class="icon danger" data-deldq="${q.id}">Hapus</button></td></tr>`).join('')||'<tr><td colspan="4">Belum ada soal.</td></tr>'}</tbody></table></div></div>`;document.querySelector('#addDQ').onclick=()=>drillQuestionModal(id);document.querySelectorAll('[data-editdq]').forEach(b=>b.onclick=()=>drillQuestionModal(id,qs.find(x=>x.id===b.dataset.editdq)));document.querySelectorAll('[data-deldq]').forEach(b=>b.onclick=async()=>{if(confirm('Hapus?')){await remove('drill_questions',b.dataset.deldq);drillQuestions(id)}})}
async function drillQuestionModal(id,row=null){const m=document.createElement('div');m.className='modal';m.innerHTML=`<div class="modal-box modal-wide"><div class="modal-head"><h3>${row?'Edit':'Tambah'} Soal Drill</h3><button id="x">×</button></div><form id="qf"><label>Pertanyaan<textarea id="qt" required>${esc(row?.question_text||'')}</textarea></label><label>Topik<input id="topic" value="${esc(row?.topic||'')}"></label><label>Kesulitan<select id="dif"><option>easy</option><option>medium</option><option>hard</option></select></label><label>Kunci<input id="key" required value="${esc(row?.answer_key||'')}"></label><label>Pilihan (JSON) <textarea id="opts">${esc(JSON.stringify(row?.option_data||[{key:'A',text:''},{key:'B',text:''},{key:'C',text:''},{key:'D',text:''}]))}</textarea></label><label>Penjelasan<textarea id="exp">${esc(row?.explanation||'')}</textarea></label><div class="modal-actions"><button type="button" id="c" class="btn btn-soft">Batal</button><button class="btn btn-primary">Simpan</button></div></form></div>`;document.body.append(m);m.querySelector('#dif').value=row?.difficulty||'medium';const close=()=>m.remove();m.querySelector('#x').onclick=m.querySelector('#c').onclick=close;m.querySelector('#qf').onsubmit=async e=>{e.preventDefault();await safe(async()=>{let od;try{od=JSON.parse(opts.value||'[]')}catch{throw Error('Format pilihan harus JSON valid.')}const o={drill_program_id:id,question_text:qt.value,topic:topic.value||null,difficulty:dif.value,answer_key:key.value.toUpperCase(),option_data:od,explanation:exp.value||null};await(row?update('drill_questions',row.id,o):insert('drill_questions',o));toast('Soal tersimpan');close();drillQuestions(id)})}}
async function studentDrill(){const student=await getStudentId();if(!student)throw Error('Profil siswa belum terhubung.');await rpc('generate_drill_targets',{p_date:today()});const targets=await list('drill_daily_targets',{filters:[{op:'eq',col:'student_id',val:student}],order:'date',ascending:false,limit:60});const t=targets.filter(x=>x.date===today());document.querySelector('#pageTitle').textContent='Drill Soal Harian';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>🎯 Drill Soal Harian</h1><p>Target latihan berdasarkan hari efektif.</p></div></div><div class="cards">${t.map(x=>stat(x.drill_program_id?.slice(0,6)||'Drill',`${x.completed_questions}/${x.target_questions}`,'Hari ini')).join('')||'<div class="card">Belum ada target hari ini.</div>'}</div><div class="card"><h3>Target Hari Ini</h3>${t.map(x=>`<div class="list-item"><div><b>${x.target_questions} soal</b><small>${x.status}</small></div><button class="btn btn-primary" data-drillstart="${x.id}">Mulai</button></div>`).join('')||'<p class="muted">Admin/guru belum membuat program drill.</p>'}</div>`;document.querySelectorAll('[data-drillstart]').forEach(b=>b.onclick=()=>startDrill(b.dataset.drillstart))}
async function startDrill(targetId){const info=await rpc('start_drill_attempt',{p_target_id:targetId});playerDrill(info)}
function playerDrill(info){const questions=info.questions||[];let idx=0;const answers={};document.querySelector('#content').innerHTML=`<div class="exam"><div class="exam-head"><div><h1>Drill Harian</h1><small id="timer">${fmtTime(Number(info.duration_seconds||0))}</small></div><span class="badge">${questions.length} SOAL</span></div><div class="card exam-main"><div id="dqbox"></div><div class="modal-actions"><button class="btn btn-soft" id="dp">Kembali</button><button class="btn btn-primary" id="dn">Lanjut</button><button class="btn btn-primary" id="ds" style="display:none">Selesai</button></div></div></div>`;const renderQ=()=>{const q=questions[idx];document.querySelector('#dqbox').innerHTML=`<div class="question-count">Soal ${idx+1} dari ${questions.length}</div><h2>${esc(q.question_text)}</h2><div class="options">${(q.option_data||[]).map(o=>`<label class="option"><input type="radio" name="da" value="${esc(o.key)}" ${answers[q.id]===o.key?'checked':''}> <b>${esc(o.key)}.</b> ${esc(o.text)}</label>`).join('')}</div>`;document.querySelectorAll('input[name=da]').forEach(x=>x.onchange=()=>answers[q.id]=x.value);dp.disabled=idx===0;dn.style.display=idx===questions.length-1?'none':'';ds.style.display=idx===questions.length-1?'':'none'};const submit=async()=>{await safe(async()=>{const r=await rpc('submit_drill_attempt',{p_attempt_id:info.attempt_id,p_answers:answers});document.querySelector('#content').innerHTML=`<div class="card hero"><h2>Drill selesai 🎉</h2><div class="cards">${stat('Benar',r.correct_answers)}${stat('Salah',r.wrong_answers)}${stat('Nilai',r.score)}</div><button class="btn btn-primary" onclick="go('drill')">Kembali ke Drill</button></div>`})};dp.onclick=()=>{if(idx>0){idx--;renderQ()}};dn.onclick=()=>{if(idx<questions.length-1){idx++;renderQ()}};ds.onclick=submit;renderQ()}

async function attendance(){
 const isTeacher=role()==='teacher';
 let schedules=[];
 if(isTeacher){const tp=(await list('teachers',{filters:[{op:'eq',col:'profile_id',val:state.user.id}],limit:1}))[0];schedules=tp?await list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',filters:[{op:'eq',col:'teacher_id',val:tp.id}],order:'weekday',ascending:true,limit:500}):[]}
 else schedules=await list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',order:'weekday',ascending:true,limit:500});
 document.querySelector('#pageTitle').textContent=isTeacher?'Presensi':'Absensi';
 const todayNo=new Date().getDay();
 document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>✓ ${isTeacher?'Presensi Guru':'Absensi'}</h1><p>${isTeacher?'Pilih sesi sesuai jadwal mengajar untuk melakukan presensi.':'Kelola presensi berdasarkan jadwal paket.'}</p></div></div><div class="cards">${schedules.map(x=>`<div class="card schedule-mini ${Number(x.weekday)===todayNo?'today':''}"><span class="badge">${Number(x.weekday)===todayNo?'HARI INI':dayNames[Number(x.weekday)]}</span><h3>${esc(x.subjects?.name||'-')}</h3><p>${esc(x.packages?.name||'-')} • ${esc(x.classes?.name||'-')}</p><strong>${esc(String(x.start_time||'').slice(0,5))}–${esc(String(x.end_time||'').slice(0,5))}</strong><button class="btn btn-primary" data-att-schedule="${x.id}" style="margin-top:12px">${Number(x.weekday)===todayNo?'Isi Presensi Hari Ini':'Buka Presensi'}</button></div>`).join('')||'<div class="card">Belum ada jadwal.</div>'}</div>`;
 document.querySelectorAll('[data-att-schedule]').forEach(b=>b.onclick=()=>scheduleAttendanceForm(b.dataset.attSchedule));
}
async function scheduleAttendanceForm(scheduleId){
 const schedule=(await list('package_schedules',{select:'*,packages(name),classes(name),subjects(name),teachers(full_name)',filters:[{op:'eq',col:'id',val:scheduleId}],limit:1}))[0]; if(!schedule)return;
 const students=await list('students',{select:'*,student_packages!inner(package_id,status,start_date,end_date)',filters:[{op:'eq',col:'class_id',val:schedule.class_id},{op:'eq',col:'student_packages.package_id',val:schedule.package_id},{op:'eq',col:'student_packages.status',val:'active'},{op:'eq',col:'status',val:'active'}],order:'full_name',limit:500});
 const date=today(); const old=await list('attendance',{filters:[{op:'eq',col:'schedule_id',val:scheduleId},{op:'eq',col:'attendance_date',val:date}],limit:500});
 document.querySelector('#pageTitle').textContent='Isi Presensi';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>${esc(schedule.subjects?.name||'Presensi')}</h1><p>${esc(dayNames[Number(schedule.weekday)])} • ${esc(String(schedule.start_time||'').slice(0,5))}–${esc(String(schedule.end_time||'').slice(0,5))} • ${esc(schedule.classes?.name||'')}</p></div><button class="btn btn-primary" id="saveAtt">Simpan Presensi</button></div><div class="card"><div class="toolbar"><span>${students.length} siswa terdaftar pada paket ini</span><span class="muted">Tanggal ${date}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Siswa</th><th>Sekolah</th><th>Status</th><th>Catatan</th></tr></thead><tbody>${students.map(s=>{const a=old.find(x=>x.student_id===s.id)||{};return `<tr><td><b>${esc(s.full_name)}</b></td><td>${esc(s.school||'-')}</td><td><select data-as="${s.id}">${['Hadir','Izin','Sakit','Alpa'].map(v=>`<option ${a.status===v?'selected':''}>${v}</option>`).join('')}</select></td><td><input data-an="${s.id}" value="${esc(a.teacher_note||'')}"></td></tr>`}).join('')||'<tr><td colspan="4" class="empty">Tidak ada siswa aktif pada paket ini.</td></tr>'}</tbody></table></div></div>`;
 document.querySelector('#saveAtt').onclick=async()=>{await safe(async()=>{for(const s of students){const payload={schedule_id:scheduleId,meeting_id:null,student_id:s.id,status:document.querySelector(`[data-as="${s.id}"]`).value,attendance_date:date,teacher_note:document.querySelector(`[data-an="${s.id}"]`).value||null};const a=old.find(x=>x.student_id===s.id);if(a)await update('attendance',a.id,payload);else await insert('attendance',payload)}toast('Presensi tersimpan');attendance()})}
}

async function reports(){if(role()==='student')return studentReports();const students=await list('students',{order:'full_name',limit:500});document.querySelector('#pageTitle').textContent='Laporan';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>📊 Laporan Hasil Belajar</h1><p>Pilih siswa untuk melihat ringkasan.</p></div></div><div class="cards">${students.map(s=>`<div class="card"><h3>${esc(s.full_name)}</h3><p>${esc(s.student_code||'')}</p><button class="btn btn-primary" data-report="${s.id}">Lihat Laporan</button></div>`).join('')||'<div class="card">Belum ada siswa.</div>'}</div>`;document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>studentReportDetail(b.dataset.report))}
async function studentReports(){const student=await getStudent();if(!student)return studentReportDetail(null,true);return studentReportDetail(student.id,true)}
async function studentReportDetail(studentId,self=false){const [s,qa,ta,da,att]=await Promise.all([list('students',{filters:[{op:'eq',col:'id',val:studentId}],limit:1}),list('quiz_attempts',{filters:[{op:'eq',col:'student_id',val:studentId},{op:'eq',col:'status',val:'completed'}],order:'completed_at',ascending:false}),list('tryout_attempts',{filters:[{op:'eq',col:'student_id',val:studentId},{op:'eq',col:'status',val:'completed'}],order:'completed_at',ascending:false}),list('drill_attempts',{filters:[{op:'eq',col:'student_id',val:studentId},{op:'eq',col:'status',val:'completed'}],order:'completed_at',ascending:false}),list('attendance',{filters:[{op:'eq',col:'student_id',val:studentId}],limit:500})]);const st=s[0];const avg=a=>a.length?Math.round(a.reduce((x,y)=>x+Number(y.score||0),0)/a.length):0;const attPct=att.length?Math.round(att.filter(x=>x.status==='Hadir').length/att.length*100):0;document.querySelector('#pageTitle').textContent='Laporan';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>Laporan: ${esc(st?.full_name)}</h1><p>${esc(st?.school||'')} • ${esc(st?.student_code||'')}</p></div><div class="quick"><button class="btn btn-soft" id="pdf">PDF</button>${st?.parent_phone?`<a class="btn btn-primary" target="_blank" href="${buildWhatsAppLink(st.parent_phone,`Laporan belajar ${st.full_name}: kehadiran ${attPct}%, rata-rata kuis ${avg(qa)}, tryout ${avg(ta)}, drill ${avg(da)}.`)}">WhatsApp</a>`:''}</div></div><div class="cards">${stat('Kehadiran',attPct+'%')}${stat('Rata-rata Kuis',avg(qa))}${stat('Rata-rata Tryout',avg(ta))}${stat('Rata-rata Drill',avg(da))}</div><div class="grid-2"><div class="card"><h3>Riwayat Kuis</h3>${qa.map(x=>`<div class="list-item"><span>${esc(x.completed_at||'')}</span><b>${x.score}</b></div>`).join('')||'<p>-</p>'}</div><div class="card"><h3>Riwayat Tryout</h3>${ta.map(x=>`<div class="list-item"><span>${esc(x.completed_at||'')}</span><b>${x.score}</b></div>`).join('')||'<p>-</p>'}</div></div><div class="card"><h3>Drill</h3>${da.slice(0,30).map(x=>`<div class="list-item"><span>${esc(x.completed_at||'')}</span><b>${x.score}</b></div>`).join('')||'<p>-</p>'}</div>`;document.querySelector('#pdf').onclick=async()=>{await safe(async()=>{const html=`<html><body><h1>TRIPLE-F EDUCATION</h1><h2>Laporan Hasil Belajar</h2><p>Nama: ${esc(st.full_name)}</p><p>Sekolah: ${esc(st.school||'-')}</p><p>Kehadiran: ${attPct}%</p><p>Rata-rata Kuis: ${avg(qa)}</p><p>Rata-rata Tryout: ${avg(ta)}</p><p>Rata-rata Drill: ${avg(da)}</p></body></html>`;const r=await generatePdfReport(html,`Laporan-${st.student_code||st.full_name}.pdf`);window.open(r.url,'_blank')})}}

async function monitoring(){const [a,q,t,d]=await Promise.all([list('attendance',{order:'created_at',ascending:false,limit:200}),list('quiz_attempts',{order:'started_at',ascending:false,limit:200}),list('tryout_attempts',{order:'started_at',ascending:false,limit:200}),list('drill_attempts',{order:'started_at',ascending:false,limit:200})]);document.querySelector('#pageTitle').textContent='Monitoring';document.querySelector('#content').innerHTML=`<div class="page-title"><div><h1>◉ Monitoring</h1><p>Aktivitas pembelajaran dan evaluasi.</p></div></div><div class="cards">${stat('Absensi',a.length)}${stat('Kuis dikerjakan',q.length)}${stat('Tryout dikerjakan',t.length)}${stat('Drill dikerjakan',d.length)}</div><div class="card"><h3>Aktivitas Terbaru</h3>${[...q.map(x=>({...x,_t:'Kuis'})),...t.map(x=>({...x,_t:'Tryout'})),...d.map(x=>({...x,_t:'Drill'}))].sort((x,y)=>String(y.started_at).localeCompare(String(x.started_at))).slice(0,30).map(x=>`<div class="list-item"><span>${x._t}</span><b>${esc(x.status)}</b><small>${esc(x.started_at||'')}</small></div>`).join('')}</div>`}
async function materials(){return genericTable('materials')}
async function profile(){document.querySelector('#pageTitle').textContent='Profil';document.querySelector('#content').innerHTML=`<div class="card"><h2>${esc(state.user.full_name)}</h2><p>${esc(state.user.email)}</p><p>Peran: ${esc(state.user.role)}</p></div>`}
async function billing(){return genericTable('billing')}

async function render(){if(!state.user)return;document.querySelector('#pageTitle').textContent=state.page==='home'?'Dashboard':state.page.toUpperCase();try{if(state.page==='home')document.querySelector('#content').innerHTML=await home();else if(state.page==='accounts')await accounts();else if(state.page==='schedules')await schedules();else if(['students','teachers','classes','subjects','packages','meetings','materials','enrollments','billing'].includes(state.page))await genericTable(state.page);else if(state.page==='quizzes')role()==='student'?await studentTests('quiz'):await questionBank('quiz');else if(state.page==='tryouts'){if(role()==='teacher'){state.page='quizzes';await questionBank('quiz')}else role()==='student'?await studentTests('tryout'):await questionBank('tryout');}else if(state.page==='drill')await drill();else if(state.page==='attendance')await attendance();else if(state.page==='reports')await reports();else if(state.page==='monitoring')await monitoring();else if(state.page==='profile')await profile();else document.querySelector('#content').innerHTML='<div class="card"><h2>Modul belum tersedia</h2></div>'}catch(e){document.querySelector('#content').innerHTML=`<div class="card"><h3>Gagal memuat</h3><p>${esc(e.message)}</p></div>`}}
(async()=>{state.user=await getCurrentUser();if(!state.user){location.href='login.html';return}shell();await render()})();
